#include <cstring>
#include <iomanip>
#include <iostream>
#include <memory>
namespace fs=std::filesystem;
using m023::need;
static void ok(nrd::Result r){need(r==nrd::Result::SUCCESS,"023 SDK result failed");}
static void bytes(const fs::path& p,const void* data,std::size_t size){std::ofstream f(p,std::ios::binary);if(size)f.write(static_cast<const char*>(data),std::streamsize(size));need(bool(f),"023 output write");}
static void numbers(std::ostream& f,const float* a,unsigned count){f<<'[';for(unsigned j=0;j<count;j++)f<<(j?",":"")<<a[j];f<<']';}
int main(int argc,char** argv){fs::path out;
 try{
    need(argc==6&&std::string(argv[1])=="--cpu-inspect"&&std::string(argv[2])=="--state"&&std::string(argv[4])=="--out","023 usage --cpu-inspect --state ORIGINAL --out NEWDIR");
    auto state=m022::load_state(argv[3]);m023::validate(state.camera);fs::path candidate=argv[5];need(!fs::exists(candidate)&&fs::is_directory(candidate.parent_path()),"023 output exists/parent absent");need(fs::create_directory(candidate),"023 output exclusive");out=candidate;fs::create_directory(out/"pipelines");fs::create_directory(out/"constants");
    for(const char* name:{"geometry-state.bin","frame-state.bin"})fs::copy_file(fs::path(argv[3])/name,out/name);bytes(out/"camera.f32",state.camera.data(),80);
    nrd::DenoiserDesc denoiser{23,nrd::Denoiser::RELAX_DIFFUSE};nrd::InstanceCreationDesc creation{};creation.denoisers=&denoiser;creation.denoisersNum=1;nrd::Instance* raw{};ok(nrd::CreateInstance(creation,raw));need(raw,"023 null SDK instance");auto destroy=[](nrd::Instance* p){nrd::DestroyInstance(*p);};std::unique_ptr<nrd::Instance,decltype(destroy)> instance(raw,destroy);
    const auto& lib=*nrd::GetLibraryDesc();const auto& desc=*nrd::GetInstanceDesc(*instance);need(lib.versionMajor==4&&lib.versionMinor==18&&lib.versionBuild==0&&lib.normalEncoding==nrd::NormalEncoding::R10_G10_B10_A2_UNORM&&lib.roughnessEncoding==nrd::RoughnessEncoding::LINEAR,"023 library version/encoding");
    nrd::RelaxSettings settings{};ok(nrd::SetDenoiserSettings(*instance,23,&settings));
    std::ofstream config(out/"instance.json");config<<std::setprecision(17)<<"{\"schema\":\"m001-nrd023-instance/1\",\"gpu_initialized\":false,\"version\":[4,18,0],\"normal_encoding\":"<<unsigned(lib.normalEncoding)<<",\"roughness_encoding\":"<<unsigned(lib.roughnessEncoding)<<",\"spaces\":{\"constants_samplers\":"<<desc.constantBufferAndSamplersSpaceIndex<<",\"resources\":"<<desc.resourcesSpaceIndex<<"},\"offsets\":{\"s\":"<<lib.spirvBindingOffsets.samplerOffset<<",\"b\":"<<lib.spirvBindingOffsets.constantBufferOffset<<",\"u\":"<<lib.spirvBindingOffsets.storageTextureAndBufferOffset<<",\"t\":"<<lib.spirvBindingOffsets.textureOffset<<"},\"constant_register\":"<<desc.constantBufferRegisterIndex<<",\"constant_max_bytes\":"<<desc.constantBufferMaxDataSize<<",\"entrypoint\":"<<std::quoted(desc.shaderEntryPoint)<<",\"samplers\":[";
    for(unsigned j=0;j<desc.samplersNum;j++)config<<(j?",":"")<<unsigned(desc.samplers[j]);config<<"],\"pools\":{";
    for(unsigned which=0;which<2;which++){const auto* pool=which?desc.transientPool:desc.permanentPool;unsigned count=which?desc.transientPoolSize:desc.permanentPoolSize;config<<(which?",":"")<<std::quoted(which?"transient":"permanent")<<":[";for(unsigned j=0;j<count;j++)config<<(j?",":"")<<"{\"index\":"<<j<<",\"format\":"<<unsigned(pool[j].format)<<",\"downsample\":"<<pool[j].downsampleFactor<<"}";config<<']';}config<<"},\"pipelines\":[";
    for(unsigned j=0;j<desc.pipelinesNum;j++){const auto& p=desc.pipelines[j];need(p.computeShaderSPIRV.bytecode&&p.computeShaderSPIRV.size>=20&&p.computeShaderSPIRV.size%4==0,"023 missing SPIRV");std::uint32_t magic{};std::memcpy(&magic,p.computeShaderSPIRV.bytecode,4);need(magic==0x07230203,"023 embedded SPIRV magic");bytes(out/"pipelines"/(std::to_string(j)+".spv"),p.computeShaderSPIRV.bytecode,p.computeShaderSPIRV.size);config<<(j?",":"")<<"{\"index\":"<<j<<",\"identifier\":"<<std::quoted(p.shaderIdentifier)<<",\"constant_data\":"<<(p.hasConstantData?"true":"false")<<",\"ranges\":[";for(unsigned k=0;k<p.resourceRangesNum;k++)config<<(k?",":"")<<"{\"type\":"<<unsigned(p.resourceRanges[k].descriptorType)<<",\"count\":"<<p.resourceRanges[k].descriptorsNum<<'}';config<<"]}";}config<<"],\"default_settings\":{\"diffuse_history\":"<<settings.diffuseMaxAccumulatedFrameNum<<",\"fast_history\":"<<settings.diffuseMaxFastAccumulatedFrameNum<<",\"atrous_iterations\":"<<settings.atrousIterationNum<<",\"diffuse_prepass_radius\":"<<settings.diffusePrepassBlurRadius<<",\"antifirefly\":"<<(settings.enableAntiFirefly?"true":"false")<<",\"checkerboard\":"<<unsigned(settings.checkerboardMode)<<",\"hit_distance_reconstruction\":"<<unsigned(settings.hitDistanceReconstructionMode)<<"}}\n";need(bool(config),"023 config output");config.close();
    std::ofstream common_file(out/"common.json");auto base=m023::common(state.camera,0,true);common_file<<std::setprecision(17)<<"{\"world_to_view\":";numbers(common_file,base.worldToViewMatrix,16);common_file<<",\"view_to_clip\":";numbers(common_file,base.viewToClipMatrix,16);common_file<<",\"time_delta_ms\":"<<base.timeDeltaBetweenFrames<<",\"denoising_range\":"<<base.denoisingRange<<",\"width\":320,\"height\":180,\"world_normals\":true,\"static_motion_zero\":true}\n";need(bool(common_file),"023 common output");
    std::ofstream journal(out/"dispatches.jsonl");std::uint64_t dispatch_total=0;
    for(unsigned iteration=0;iteration<65;iteration++){unsigned frame=iteration==64?0:iteration;auto common=m023::common(state.camera,frame,iteration==0||iteration==64);ok(nrd::SetCommonSettings(*instance,common));const nrd::DispatchDesc* dispatches{};std::uint32_t count{};ok(nrd::GetComputeDispatches(*instance,&denoiser.identifier,1,dispatches,count));need(dispatches&&count>0&&count<=128,"023 dispatch count");journal<<"{\"iteration\":"<<iteration<<",\"frame\":"<<frame<<",\"clear\":"<<((iteration==0||iteration==64)?"true":"false")<<",\"dispatches\":[";
      for(unsigned j=0;j<count;j++){const auto& d=dispatches[j];need(d.pipelineIndex<desc.pipelinesNum&&d.gridWidth>0&&d.gridHeight>0&&d.constantBufferDataSize<=desc.constantBufferMaxDataSize,"023 SDK dispatch range");std::string file=std::to_string(iteration)+"-"+std::to_string(j)+".bin";bytes(out/"constants"/file,d.constantBufferData,d.constantBufferDataSize);journal<<(j?",":"")<<"{\"name\":"<<std::quoted(d.name)<<",\"identifier\":"<<d.identifier<<",\"pipeline\":"<<d.pipelineIndex<<",\"grid\":["<<d.gridWidth<<','<<d.gridHeight<<"],\"constant_bytes\":"<<d.constantBufferDataSize<<",\"constant_file\":"<<std::quoted(file)<<",\"matches_previous\":"<<(d.constantBufferDataMatchesPreviousDispatch?"true":"false")<<",\"resources\":[";
        for(unsigned k=0;k<d.resourcesNum;k++){const auto& resource=d.resources[k];journal<<(k?",":"")<<"{\"descriptor_type\":"<<unsigned(resource.descriptorType)<<",\"type\":"<<unsigned(resource.type)<<",\"name\":"<<std::quoted(nrd::GetResourceTypeString(resource.type))<<",\"pool_index\":"<<resource.indexInPool<<'}';}journal<<"]}";
      }journal<<"]}\n";need(bool(journal),"023 journal output");dispatch_total+=count;
    }
    auto pipeline_count=desc.pipelinesNum;instance.reset();std::ofstream f(out/"complete.json");f<<"{\"schema\":\"m001-nrd023-real-sdk-cpu-probe/1\",\"complete\":true,\"gpu_initialized\":false,\"api_frames\":65,\"consecutive_frames\":64,\"explicit_reset_frames\":1,\"dispatches\":"<<dispatch_total<<",\"pipelines\":"<<pipeline_count<<",\"quality_admitted\":false,\"accepted_timing\":false}\n";need(bool(f),"023 complete write");return 0;
 }catch(const std::exception& e){if(!out.empty())std::ofstream(out/"failure.txt")<<e.what()<<'\n';std::cerr<<e.what()<<'\n';return 2;}
}
